css:
   .web-footer {
    display: none;
  }
 .issue-card {
  background: #fff;
  border-radius: 10px;
  box-shadow: 0 1px 5px rgba(0,0,0,0.08);
  margin-bottom: 20px;
  overflow: hidden;
}

.issue-header {
  font-size: 16px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px;
  background-color: #f1f1f1;
  cursor: pointer;
}
.arrow {
  margin-right: 6px;
}
#serial-info{
    text-align:center;
    padding:10px 0;
    background-color:#cbe091;
}
.status-badge {
  padding: 3px 8px;
  font-size: 12px;
  border-radius: 10px;
  font-weight: bold;
  text-transform: uppercase;
}
.status-badge.green {
  background-color: #d4edda;
  color: #155724;
}
.status-badge.gray {
  background-color: #e2e3e5;
  color: #383d41;
}
.status-badge.blue {
  background-color: #cce5ff;
  color: #004085;
}

.issue-body {
  font-size: 14px;
  padding: 12px;
  display: none;
}
.task-section {
  padding: 10px;
  background-color: #f8f9fa;
  border-radius: 6px;
  margin-top: 10px;
}
.task-card {
  background-color: #ffffff;
  padding: 8px;
  border: 1px solid #dee2e6;
  border-radius: 5px;
  margin-bottom: 8px;
}
.task-footer {
  display: flex;
  justify-content: space-between;
  font-size: 13px;
  margin-top: 5px;
}
.task-status {
  color: #007bff;
  font-weight: bold;
}
.task-assigned {
  color: #6c757d;
}

 .issue-block {
  margin-bottom: 15px;
  padding: 10px;
  background-color: #ffe6e6;
  border-radius: 6px;
}
.task-list ul {
  padding-left: 20px;
  margin: 5px 0;
}
.garanti-card {
  margin-bottom: 10px;
  padding: 8px;
  background: #eef6ff;
  border-left: 4px solid #007bff;
}
   .item-box {
    padding: 20px 25px;
    border-radius: 10px;
    box-shadow: 0 3px 12px rgba(0, 0, 0, 0.05);
}

.info-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
    gap: 12px;
    margin-bottom: 10px;
}

.info-item {
    background: #f6f9fc;
    padding: 10px 15px;
    border-radius: 6px;
    font-size: 13.5px;
    box-shadow: 0 1px 2px rgba(0,0,0,0.03);
    border-left: 3px solid #4b7bec;
}
.info-item span {
    font-weight: 600;
}

.item-wrapper h3 {
    font-size: 20px;
    margin-bottom: 15px;
}
.item-wrapper {
background-color: #f5f6f8;

}

.btn-wrapper {
    margin-top: 20px;
}

.btn-wrapper button {
    padding: 10px 20px;
    font-size: 15px;
    border-radius: 8px;
}

/* Modern Accordion Styles */
.issue-accordion-card {
  border-radius: 16px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.07);
  margin-bottom: 18px;
  background: #fff;
  overflow: hidden;
  border: none;
}
.issue-accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 20px;
  font-size: 17px;
  font-weight: 600;
  cursor: pointer;
  background: #f6f9fc;
  border-bottom: 1px solid #f0f0f0;
}
.issue-accordion-header .status {
  font-size: 14px;
  font-weight: 500;
  border-radius: 8px;
  padding: 4px 12px;
  background: #eafaf1;
  color: #28a745;
}
.issue-accordion-header .status.closed {
  background: #f5f5f5;
  color: #888;
}
.issue-accordion-content {
  display: none;
  padding: 18px 20px;
  background: #fff;
  text-align: left;
}
.issue-accordion-header .toggle-icon {
  margin-right: 12px;
  font-size: 1.3em;
  color: #4b7bec;
}
.issue-detail-row {
  margin-bottom: 10px;
  font-size: 15px;
}
.issue-detail-row strong {
  color: #4b7bec;
  font-weight: 600;
}

/* Main Info Card Styles */
.main-info-card {
  background: #eafaf1;
  border-radius: 18px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.07);
  padding: 24px 18px 18px 18px;
  text-align: center;
  margin-bottom: 18px;
  height: 100vh;
}
.success-icon {
  color: #28a745;
  font-size: 38px;
  margin-bottom: 8px;
}
.main-info-title {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 8px;
}
.main-info-id {
  background: #fff;
  display: inline-block;
  padding: 6px 18px;
  border-radius: 12px;
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 12px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.04);
}
.main-info-btn {
  background: #4b7bec;
  color: #fff;
  border: none;
  border-radius: 8px;
  padding: 10px 22px;
  font-size: 16px;
  font-weight: 600;
  margin-top: 10px;
  cursor: pointer;
  transition: background 0.2s;
}
.main-info-btn:hover {
  background: #3867d6;
}

/* Info Cards Grid */
.info-cards-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  margin-bottom: 18px;
}
@media (max-width: 768px) {
  .info-cards-grid {
    grid-template-columns: 1fr;
  }
}
.info-card {
  background: #fff;
  border-radius: 16px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.07);
  padding: 18px 12px;
  text-align: center;
  transition: box-shadow 0.2s;
  cursor: pointer;
}
.info-card:hover {
  box-shadow: 0 4px 18px rgba(0,0,0,0.12);
}
.info-card-icon {
  font-size: 32px;
  margin-bottom: 8px;
}
.info-card.blue .info-card-icon { color: #4b7bec; }
.info-card.orange .info-card-icon { color: #f7b731; }
.info-card.red .info-card-icon { color: #eb3b5a; }
.info-card.pink .info-card-icon { color: #fa8231; }
.info-card-title {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 4px;
}
.info-card-desc {
  font-size: 13px;
  color: #555;
}

@media (max-width: 768px) {
    .item-box {
        padding: 20px;
    }

    .btn-wrapper button {
        width: 100%;
    }
}
